/* The code segments the game DMAs, for the native port (M2). Host side. On the N64 the resident engine segments
 * (engine1/2/4, evt, entity) and every overlay (maps, battle areas, moves, partners, effects, the pause and file
 * menus) are copied from the ROM into their VRAM windows; natively all of them are linked in, so a DMA of a code
 * segment's range is not a copy (and its "VRAM" destination is no host address). The ranges come from the decomp's
 * splat.yaml (build/game/port_segtab.c, generated by tools/port/gen_build.py).
 *
 * The N64's copy also puts an overlay's .data back to its linked values each time it is loaded: a map on entry and
 * again after every battle, a battle area per battle, a move per use, the battle code per battle, and so on. The game
 * relies on it (a skipped demo battle left the battle code's EndDemoWhiteOut set, and the next battle crashed; Power
 * Bounce's hit chance, the star spirits' delays, the opening story's pages, ...). So when the game loads an overlay
 * (a DMA from its first byte), its data (gen_build.py's OVL lists, __pm64ovl_<segment>_start/_end in the asset region)
 * is copied back from the pristine region (port_state.c: assets.bin on the card, a copy on the desktop). The .bss is
 * left as it is, as on the N64. PM64_OVLRESET=0 (A/B tests): no restore, as before; PM64_OVLLOG=1 (tests): a log line
 * per restore. */
#include <stdlib.h>
#include <string.h>
#include "port.h"

extern const struct { uint32_t start, end; const char *name; uint8_t *data, *data_end; } port_code_segs[];
extern const int port_code_segs_n;
extern uint8_t __assets_start[];

int port_code_segment(uint32_t rom_start, uint32_t rom_end, int *seg_index) {
    int lo = 0, hi = port_code_segs_n - 1;
    while (lo <= hi) { /* the table is in ROM order */
        const int mid = (lo + hi) / 2;
        if (rom_start < port_code_segs[mid].start) hi = mid - 1;
        else if (rom_start >= port_code_segs[mid].end) lo = mid + 1;
        else {
            if (rom_end > port_code_segs[mid].end)
                port_log("segments: DMA 0x%08X..0x%08X runs past code segment %s (ends 0x%08X)\n", rom_start, rom_end,
                         port_code_segs[mid].name, port_code_segs[mid].end);
            if (seg_index) *seg_index = mid;
            return 1;
        }
    }
    return 0;
}

void port_segment_loaded(int seg, uint32_t rom_start) {
    static int sOn = -1, sLog, sWarned;
    if (sOn < 0) {
        const char *e = getenv("PM64_OVLRESET");
        sOn = !(e && e[0] == '0');
        sLog = (e = getenv("PM64_OVLLOG")) != NULL && e[0] == '1';
        port_log("segments: overlay data %s on load (PM64_OVLRESET)\n", sOn ? "restored" : "kept");
    }
    if (!sOn || seg < 0 || seg >= port_code_segs_n || rom_start != port_code_segs[seg].start) return;
    uint8_t *d = port_code_segs[seg].data;
    const uint32_t n = (uint32_t) (port_code_segs[seg].data_end - d);
    if (d == NULL || n == 0) return;
    if (!port_state_pristine_bytes((uint32_t) (d - __assets_start), d, n)) {
        if (!sWarned++) port_log("segments: no pristine region: overlay data kept as it was (%s)\n", port_code_segs[seg].name);
        return;
    }
    if (sLog) port_log("segments: %s loaded at game frame %u, %u data bytes restored\n", port_code_segs[seg].name,
                       (unsigned) port_frame, (unsigned) n);
}
